const n0=v=>Math.round(Number(v)||0),n1=v=>(Number(v)||0).toFixed(1),pct=v=>Math.round((Number(v)||0)*100)+'%',avg=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
