let profile=null,data=null,googleLive=null,googleLastAttempt=null,localEvents=null,eventLastAttempt=null,selectedDate=restaurantNow().date,currentView='dashboard',refreshTimer=null,clockTimer=null,settings=loadSettings(),dailyMode='hourly';
const GOOGLE_AUTO_SLOTS=[10*60,12*60,14*60,16*60,18*60,20*60];
const GOOGLE_CACHE_KEY='fztraffic_google_live_cache_v2',GOOGLE_SCHEDULE_KEY='fztraffic_google_schedule_v3_6x';
const EVENT_CACHE_KEY='fztraffic_local_events_cache_v1',EVENT_SCHEDULE_KEY='fztraffic_event_schedule_v1',EVENT_AUTO_MINUTE=8*60+30;
const requestedView=new URLSearchParams(location.search).get('view');if(['dashboard','live','google','events','daily','calendar','staffing','advisor','history','accuracy','settings'].includes(requestedView))currentView=requestedView;
function loadSettings(){try{return{...DEFAULT_SETTINGS,...JSON.parse(localStorage.getItem('fztraffic_settings_v1')||'{}')}}catch{return{...DEFAULT_SETTINGS}}}
function saveSettings(){localStorage.setItem('fztraffic_settings_v1',JSON.stringify(settings))}
function loadGoogleCache(){try{const x=JSON.parse(localStorage.getItem(GOOGLE_CACHE_KEY)||'null');return x?.ok?{...x,cacheState:'local'}:null}catch{return null}}
function saveGoogleCache(x){if(x?.ok)try{const clean={...x};delete clean.lastKnownGood;delete clean.lastAttemptError;delete clean.lastAttemptAt;delete clean.cacheState;localStorage.setItem(GOOGLE_CACHE_KEY,JSON.stringify(clean))}catch{}}
function googleScheduleState(){const now=restaurantNow();let x=null;try{x=JSON.parse(localStorage.getItem(GOOGLE_SCHEDULE_KEY)||'null')}catch{}if(!x||x.date!==now.date)x={date:now.date,lastSlot:null,autoFetches:0};return x}
function saveGoogleSchedule(x){try{localStorage.setItem(GOOGLE_SCHEDULE_KEY,JSON.stringify(x))}catch{}}
function latestDueGoogleSlot(){const now=restaurantNow(),st=googleScheduleState(),due=GOOGLE_AUTO_SLOTS.filter(m=>m<=now.total).pop();return due!=null&&(st.lastSlot==null||due>st.lastSlot)?due:null}
function nextGoogleSlot(){const now=restaurantNow();return GOOGLE_AUTO_SLOTS.find(m=>m>now.total)??null}
function googleScheduleLabel(){const st=googleScheduleState(),next=nextGoogleSlot();return `10 AM • 12 PM • 2 PM • 4 PM • 6 PM • 8 PM CT • ${st.autoFetches||0} automatic today • ${next==null?'Next tomorrow 10:00 AM':'Next '+formatMinute(next)}`}
function markGoogleSlot(slot){const st=googleScheduleState();st.lastSlot=slot;st.autoFetches=Math.min(6,(st.autoFetches||0)+1);saveGoogleSchedule(st)}
function coverNearbySlotWithManual(){const now=restaurantNow(),st=googleScheduleState(),candidates=GOOGLE_AUTO_SLOTS.filter(m=>(st.lastSlot==null||m>st.lastSlot)&&Math.abs(m-now.total)<=90).sort((a,b)=>Math.abs(a-now.total)-Math.abs(b-now.total));const slot=candidates[0];if(slot==null)return null;st.lastSlot=slot;st.manualCoveredSlot=slot;saveGoogleSchedule(st);return slot}
googleLive=loadGoogleCache();
function loadEventCache(){try{const x=JSON.parse(localStorage.getItem(EVENT_CACHE_KEY)||'null');return x?.ok?{...x,cacheState:'local'}:null}catch{return null}}
function saveEventCache(x){if(x?.ok&&Array.isArray(x.events)&&x.events.length)try{const clean={...x};delete clean.lastKnownGood;delete clean.lastAttemptError;delete clean.cacheState;localStorage.setItem(EVENT_CACHE_KEY,JSON.stringify(clean))}catch{}}
function eventScheduleState(){const now=restaurantNow();let x=null;try{x=JSON.parse(localStorage.getItem(EVENT_SCHEDULE_KEY)||'null')}catch{}if(!x||x.date!==now.date)x={date:now.date,done:false,automatic:0};return x}
function saveEventSchedule(x){try{localStorage.setItem(EVENT_SCHEDULE_KEY,JSON.stringify(x))}catch{}}
function eventScheduleLabel(){const st=eventScheduleState(),now=restaurantNow();return st.done?`Today's local-event check completed • next automatic check tomorrow after 8:30 AM CT`:(now.total<EVENT_AUTO_MINUTE?'Next automatic check after 8:30 AM CT':'Local-event check due now')}
function markEventChecked(manual=false){const st=eventScheduleState();st.done=true;st.automatic=manual?0:1;st.manual=manual;st.checkedAt=Date.now();saveEventSchedule(st)}
function shouldAutoRefreshEvents(){const now=restaurantNow(),st=eventScheduleState();return now.total>=EVENT_AUTO_MINUTE&&!st.done}
localEvents=loadEventCache();

function smartForecastDay(date){return blendForecastWithEvents(blendForecastWithGoogle(forecastDay(data,date,settings),googleLive,settings),localEvents,settings)}
function smartForecastRange(start,days){return forecastRange(data,start,days,settings).map(f=>blendForecastWithEvents(blendForecastWithGoogle(f,googleLive,settings),localEvents,settings))}
function googleBadge(){if(googleLive?.ok){if(googleLive.lastKnownGood)return `<span class="google-badge cached">G MAPS • LAST GOOD</span>`;if(Number.isFinite(googleLive.liveScore))return `<span class="google-badge good">G LIVE • ${Math.round(googleLive.liveScore)}% LIVE</span>`;return `<span class="google-badge good">G MAPS • POPULAR TIMES</span>`}return `<span class="google-badge waiting">G MAPS • WAITING</span>`}
function googleCurrentCard(){if(!googleLive?.ok){const next=nextGoogleSlot(),nextText=next==null?'tomorrow 10:00 AM':formatMinute(next);return `<div class="card google-live-card disconnected"><div class="split-head"><div><h2>GOOGLE MAPS POPULAR TIMES / LIVE BUSYNESS</h2><div class="subtle">External signal for The Juicy Seafood and Bar</div></div>${googleBadge()}</div><div class="empty"><b>Waiting for a successful Google Popular Times sync.</b><br>${esc(googleLastAttempt?.error||googleLive?.error||`Next scheduled Google check: ${nextText} CT.`)}</div></div>`}const ls=Number.isFinite(googleLive.liveScore)?Math.round(googleLive.liveScore):null,us=Number.isFinite(googleLive.usualScore)?Math.round(googleLive.usualScore):null,delta=Number.isFinite(googleLive.delta)?Math.round(googleLive.delta):null,lastGood=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'}).format(new Date(googleLive.fetchedAt||Date.now())),staleNote=googleLive.lastKnownGood?` • Latest Google check did not include Popular Times, so FZ is keeping the last successful Google pattern.`:'';return `<div class="card google-live-card"><div class="split-head"><div><h2>GOOGLE MAPS POPULAR TIMES / LIVE BUSYNESS</h2><div class="subtle">${googleLive.lastKnownGood?'Last-known-good external signal':'Auto-updated external traffic signal'} • ${esc(googleLive.source||'Google Maps')}</div></div>${googleBadge()}</div><div class="google-live-grid section-gap"><div class="google-score"><b>${ls==null?'—':ls+'%'}</b><span>Live busyness</span></div><div class="google-score"><b>${us==null?'—':us+'%'}</b><span>Usually now</span></div><div class="google-score"><b class="${delta==null?'':delta>8?'red':delta<-8?'green':'orange'}">${delta==null?'—':(delta>0?'+':'')+delta}</b><span>Live vs usual</span></div></div><div class="signal ${delta!=null&&delta>12?'danger':delta!=null&&delta>5?'warn':''}">${esc(googleLive.info||'Google Popular Times available.')}${googleLive.timeSpent?` • ${esc(googleLive.timeSpent)}`:''}</div><div class="note">Popular Times retained across devices • Last successful Google sync ${lastGood}${staleNote}</div></div>`}


function impactClass(label){return label==='High'?'very':label==='Medium'?'busy':'normal'}
function eventTime(e){return Number.isFinite(e?.startMinute)?formatMinute(e.startMinute):(e?.when||'Time not listed')}
function eventBadge(summary){if(!summary?.count)return '<span class="event-badge none">NO EVENT UPLIFT</span>';return `<span class="event-badge ${String(summary.maxImpact||'Low').toLowerCase()}">${esc(summary.maxImpact)} IMPACT • ${summary.count} EVENT${summary.count===1?'':'S'}</span>`}
function eventWatchCard(){const now=restaurantNow(),rows=upcomingEvents(localEvents,now.date,7),high=rows.filter(e=>e.impactLabel==='High').length,last=localEvents?.fetchedAt?new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(localEvents.fetchedAt)):'—';if(!localEvents?.ok)return `<div class="card event-watch disconnected"><div class="split-head"><div><h2>LOCAL EVENT IMPACT WATCH</h2><div class="subtle">Huntsville • Madison • nearby North Alabama</div></div><span class="event-badge waiting">WAITING</span></div><div class="empty"><b>Waiting for the daily local-event scan.</b><br>${esc(eventLastAttempt?.error||localEvents?.error||eventScheduleLabel())}</div></div>`;return `<div class="card event-watch"><div class="split-head"><div><h2>LOCAL EVENT IMPACT WATCH</h2><div class="subtle">Concerts • expos • conventions • festivals • sports</div></div><span class="event-badge ${high?'high':rows.length?'medium':'none'}">${rows.length} NEXT 7 DAYS${high?' • '+high+' HIGH':''}</span></div>${rows.length?`<div class="event-list section-gap">${rows.slice(0,4).map(e=>`<div class="event-row"><div class="event-date"><b>${esc(e.date.slice(5))}</b><span>${esc(eventTime(e))}</span></div><div class="event-main"><b>${esc(e.title)}</b><span>${esc(e.venue||e.area||'Local area')} • ${esc(e.category||'Event')}</span></div><div class="event-impact ${String(e.impactLabel||'Low').toLowerCase()}"><b>${esc(e.impactLabel||'Low')}</b><span>up to +${n0(e.upliftPct)}%</span></div></div>`).join('')}</div>`:'<div class="empty">No major local events were returned for the upcoming window.</div>'}<div class="note">Last event sync ${esc(last)} • ${esc(eventScheduleLabel())}. Event uplift is conservative and capped; it is a demand signal, not an attendance count. <button class="link-button" data-go="events">View Event Intelligence</button></div></div>`}
function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function prettyDate(date){return new Intl.DateTimeFormat('en-US',{weekday:'long',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}
function actualDaySummary(date){const ev=(data?.events||[]).filter(e=>e.date===date),hours=actualHourly(data,date),peak=hours.slice().sort((a,b)=>b.tables-a.tables||b.guests-a.guests)[0]||null;return{date,tables:ev.length,guests:ev.reduce((s,e)=>s+(+e.people||0),0),peak}}
function sameWeekdayHistory(date,limit=8){return [...new Set((data?.events||[]).map(e=>e.date).filter(d=>d<date&&dayOfWeek(d)===dayOfWeek(date)))].sort().reverse().slice(0,limit).map(actualDaySummary)}
function weekStartMonday(date){const d=new Date(date+'T12:00:00Z'),w=d.getUTCDay()||7;d.setUTCDate(d.getUTCDate()-w+1);return d.toISOString().slice(0,10)}
function weeklyTrendRows(limit=8){const m=new Map;for(const e of(data?.events||[])){const k=weekStartMonday(e.date),x=m.get(k)||{period:k,tables:0,guests:0,dates:new Set};x.tables++;x.guests+=+e.people||0;x.dates.add(e.date);m.set(k,x)}return[...m.values()].sort((a,b)=>a.period.localeCompare(b.period)).slice(-limit).map(x=>({...x,recordedDays:x.dates.size,avgTables:x.dates.size?x.tables/x.dates.size:0}))}
function monthlyTrendRows(limit=6){const m=new Map;for(const e of(data?.events||[])){const k=e.date.slice(0,7),x=m.get(k)||{period:k,tables:0,guests:0,dates:new Set};x.tables++;x.guests+=+e.people||0;x.dates.add(e.date);m.set(k,x)}return[...m.values()].sort((a,b)=>a.period.localeCompare(b.period)).slice(-limit).map(x=>({...x,recordedDays:x.dates.size,avgTables:x.dates.size?x.tables/x.dates.size:0}))}
function trendBars(rows){const max=Math.max(1,...rows.map(x=>x.avgTables));return`<div class="chart">${rows.map(x=>`<div class="bar-col"><i style="height:${Math.max(2,x.avgTables/max*180)}px"></i><b>${x.period.slice(5)}</b></div>`).join('')}</div>`}
function clock(){const now=new Date();$('clock').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'}).format(now);$('todayLabel').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',weekday:'long',month:'short',day:'numeric',year:'numeric'}).format(now)}
function levelClass(level){return level==='Peak'?'peak':level==='Very Busy'?'very':level==='Busy'?'busy':'normal'}
function levelColor(level){return level==='Peak'?'#7a5cff':level==='Very Busy'?'#ff4057':level==='Busy'?'#ff8b19':level==='Normal'?'#f2b317':'#16b96c'}
function dateMinuteFromEvent(e){if(e.seatedAt){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(e.seatedAt)).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return (+p.hour)*60+(+p.minute)}return Number.isInteger(+e.hour)?(+e.hour)*60:null}
function last60Tables(){const now=restaurantNow();return(data?.events||[]).filter(e=>e.date===now.date&&e.seatedAt&&(()=>{const m=dateMinuteFromEvent(e);return m>now.total-60&&m<=now.total})()).length}
function todayTraffic(){const now=restaurantNow(),ev=(data?.events||[]).filter(e=>e.date===now.date);return{tables:ev.length,guests:ev.reduce((s,e)=>s+(Number(e.people)||0),0),last60:last60Tables()}}
function reservationsNext(minutes=120){const now=restaurantNow();return(data?.reservations||[]).filter(r=>r.date===now.date&&(()=>{const m=String(r.time||'').match(/^(\d+):(\d+)/);if(!m)return false;const x=+m[1]*60+(+m[2]);return x>=now.total&&x<=now.total+minutes})())}
function windowSum(f,endMinute){const now=restaurantNow();const slots=f.slots.filter(s=>s.start>now.total&&s.start<=endMinute);return{tables:slots.reduce((a,s)=>a+s.tables,0),guests:slots.reduce((a,s)=>a+s.guests,0),index:slots.length?Math.max(...slots.map(s=>s.trafficIndex)):0,confidence:slots.length?Math.round(slots.reduce((a,s)=>a+s.confidence,0)/slots.length):f.confidence}}
function kpi(label,value,meta,cls='blue'){return`<div class="card kpi"><div class="label">${esc(label)}</div><div class="value ${cls}">${esc(value)}</div><div class="meta">${meta}</div></div>`}
function titleRow(title,sub,actions=''){return`<div class="title-row"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="selector-row">${actions}</div></div>`}
function mini(label,value,cls=''){return`<div class="mini"><small>${esc(label)}</small><b class="${cls}">${esc(value)}</b></div>`}
function forecastExplain(f){const pace=(f.live.pace-1)*100,mom=(f.live.momentum-1)*100;const live=f.date===restaurantNow().date?mini('Live pace / momentum',`${pace>=0?'+':''}${Math.round(pace)}% / ${mom>=0?'+':''}${Math.round(mom)}%`):'';const ev=f.eventImpact?.count?mini('Local event signal',`${f.eventImpact.count} event${f.eventImpact.count===1?'':'s'} • ${f.eventImpact.maxImpact}${f.eventImpact.maxUpliftPct?` • up to +${Math.round(f.eventImpact.maxUpliftPct)}%`:''}`):mini('Local event signal',localEvents?.ok?'No event uplift':'Waiting for event scan');return`<div class="forecast-reason">${mini('Same weekday history',`${f.recordedExactDays} recorded ${dayName(f.date)}s`)}${mini('Day-group fallback',`${f.recordedGroupDays} ${f.dayGroup} days`)}${mini('Recent 28-day trend',`${f.trend>=1?'+':''}${Math.round((f.trend-1)*100)}%`)}${mini('Month / season factor',`${f.season>=1?'+':''}${Math.round((f.season-1)*100)}%`)}${live}${f.external?.connected?mini('Google Maps signal',f.external.liveScore!=null?`${Math.round(f.external.liveScore)}% live • ${Math.round((f.external.liveWeight||0)*100)}% weight`:`Typical Popular Times • ${Math.round((f.external.patternWeight||0)*100)}% weight`):mini('Google Maps signal','Offline / not connected')}${ev}</div>`}
function hourlyChart(f){const actual=new Map(actualHourly(data,f.date).map(x=>[x.hour,x.tables]));const max=Math.max(1,...f.hourly.map(h=>Math.max(h.tables,actual.get(h.hour)||0)));return`<div class="chart">${f.hourly.map(h=>{const a=actual.get(h.hour)||0;return`<div class="bar-col ${f.date===restaurantNow().date&&h.hour===Math.floor(restaurantNow().total/60)?'now':''}"><div class="bar-pair"><i title="Predicted ${n1(h.tables)}" style="height:${Math.max(2,h.tables/max*170)}px"></i><i class="actual" title="Actual ${a}" style="height:${Math.max(2,a/max*170)}px"></i></div><b>${h.hour%12||12}${h.hour<12?'a':'p'}</b></div>`}).join('')}</div><div class="legend"><span><i style="background:#1478ff"></i>Predicted</span><span><i style="background:#ff7a25"></i>Actual</span></div>`}
function liveForecastCard(f){const now=restaurantNow(),floor=data.floor,load=floor.total?floor.occupied/floor.total:0;const windows=[30,60,90].map(m=>({m,sum:windowSum(f,now.total+m),floor:modeledFloor(data,f,now.total+m,settings)}));return`<div class="card"><div class="split-head"><div><h2>LIVE FORECAST</h2><div class="subtle">Current status + next 90 minutes • auto-updates every ${settings.liveUpdateMinutes} minutes</div></div><span class="pill">LIVE</span></div><div class="forecast-wrap"><div class="gauge" style="--p:${Math.round(load*100)}"><div><b>${Math.round(load*100)}%</b><span>Actual Floor Load</span><strong class="${load>.8?'red':load>.6?'orange':'green'}">${load>.85?'VERY BUSY':load>.65?'BUSY':load>.35?'NORMAL':'LIGHT'}</strong></div></div><div><div class="rows">${windows.map(w=>`<div class="frow"><span>+${w.m} min</span><div class="meter"><i style="width:${w.sum.index}%"></i></div><strong>${n0(w.sum.tables)} tbl • ${w.sum.index}</strong></div>`).join('')}</div><div class="mini-grid">${mini('Expected Peak',f.peakSlot?formatMinute(f.peakSlot.start):'—','red')}${mini('Modeled +60 Floor',windows[1].floor?pct(windows[1].floor.load):'—','orange')}${mini('Forecast Confidence',`${f.confidence}%`,'blue')}</div></div></div>${forecastExplain(f)}<div class="note">Floor Load NOW is measured from Quick Board table status. Future Floor Load is modeled using current occupied tables, forecast arrivals, and an average ${settings.avgDiningMinutes}-minute dining duration.</div></div>`}
function todayAtGlance(f){const ev=eventDaySummary(localEvents,f.date);return`<div class="card"><h2>TODAY AT A GLANCE</h2><div class="table-wrap"><table class="data-table"><tbody><tr><td>Predicted Total Tables</td><td><b>${n0(f.totalTables)}</b></td></tr><tr><td>Predicted Total Guests</td><td><b>${n0(f.totalGuests)}</b></td></tr><tr><td>Expected Peak</td><td><b>${f.peakSlot?formatMinute(f.peakSlot.start):'—'}</b></td></tr><tr><td>Slow Window</td><td><b>${f.slowSlot?formatMinute(f.slowSlot.start):'—'}</b></td></tr><tr><td>Known Reservations</td><td><b>${(data.reservations||[]).filter(r=>r.date===f.date).length}</b></td></tr><tr><td>Local Event Impact</td><td><b>${ev.count?`${ev.maxImpact} • ${ev.count} event${ev.count===1?'':'s'}`:'None detected'}</b></td></tr><tr><td>Model Confidence</td><td><b>${f.confidence}%</b></td></tr></tbody></table></div></div>`}
function renderDashboard(){const now=restaurantNow(),f=smartForecastDay(now.date),floor=data.floor,traffic=todayTraffic(),week=smartForecastRange(now.date,7),staff=staffingRecommendation(data,f,now.total+60,settings),adv=advisor(data,f,settings);$('dashboard').innerHTML=titleRow('Restaurant Intelligence Dashboard','Real-time floor NOW + persistent seating history')+`<div class="grid4">${kpi('Occupied Tables • NOW',floor.total?`${floor.occupied} / ${floor.total}`:'—',`Live floor only • Seated ${floor.seated} • Reserved ${floor.reserved}`,'blue')}${kpi('Current Guests • NOW',floor.currentGuests||0,'Live floor only • resets when tables become Ready','green')}${kpi('Tables Served • TODAY',traffic.tables,`Persistent history • ${traffic.last60} seated in last 60 min`,'purple')}${kpi('Guests Served • TODAY',traffic.guests,'Persistent history • survives Ready and Clear Shift','orange')}</div><div class="section-gap">${googleCurrentCard()}</div><div class="section-gap">${eventWatchCard()}</div><div class="card section-gap"><h2>FZ PERSISTENT SEATING LEDGER</h2><div class="status-line"><span class="status-chip">Server Intelligence logic</span><span class="status-chip">analyticsV1 archive + live Board</span><span class="status-chip">Ready/Clear Shift safe</span></div><div class="note">Traffic totals use persistent seating events, not current table status. When a table becomes Ready, only Occupied NOW changes; Tables/Guests Served TODAY stay recorded. Clear Shift falls back to the persistent analytics archive.</div></div><div class="grid2 section-gap">${liveForecastCard(f)}${todayAtGlance(f)}</div><div class="grid2 section-gap"><div class="card"><div class="split-head"><div><h2>HOURLY FORECAST • TODAY</h2><div class="subtle">Predicted vs actual tables</div></div><button class="action" data-go="daily">View Details</button></div>${hourlyChart(f)}</div><div class="card"><h2>STAFFING INTELLIGENCE</h2><div class="staff-row section-gap"><div class="staff-box"><span class="subtle">Active Servers</span><b>${data.staff.active}</b><small>Break ${data.staff.onBreak} • Cut ${data.staff.cut}</small></div><div class="staff-box"><span class="subtle">Recommended +60m</span><b>${staff.recommended}</b><small>Baseline ${staff.baseline}</small></div><div class="staff-box"><span class="subtle">Status</span><b class="${staff.diff<0?'red':staff.diff>1?'orange':'green'}">${staff.status}</b><small>${staff.floor?`Modeled floor ${pct(staff.floor.load)}`:'Floor model unavailable'}</small></div></div><div class="signal ${staff.diff<0?'danger':staff.diff>1?'warn':''}">${staff.diff<0?'Do not cut • forecast needs '+Math.abs(staff.diff)+' more active server(s).':staff.diff>1?'Coverage is above forecast need. Review cut only after floor and service conditions are confirmed.':'Current coverage matches forecast need.'}</div></div></div><div class="grid2 section-gap"><div class="card"><div class="split-head"><h2>7-DAY FORECAST</h2><button class="action" data-go="calendar">30 Days</button></div><div class="week section-gap">${week.map(x=>`<div class="day-card" data-date="${x.date}"><span>${x.dayName.slice(0,3)}<br>${x.date.slice(5)}</span><b style="color:${levelColor(x.peakSlot?.level||'Normal')}">${n0(x.totalTables)}</b><small>${x.peakSlot?.level||'—'} • ${x.confidence}%${x.eventImpact?.count?`<br>🎟 ${x.eventImpact.count} • ${x.eventImpact.maxImpact}`:''}</small></div>`).join('')}</div></div><div class="card"><h2>BREAK & CUT ADVISOR</h2><div class="advisor-grid section-gap"><div class="advisor-box"><div class="subtle">Recommended Break Window</div><div class="big-advice purple">${adv.breakText}</div><small>Low-demand window before expected peak.</small></div><div class="advisor-box cut"><div class="subtle">Potential Cut Window</div><div class="big-advice red">${adv.cutText}</div><small>Decision support only. Manager confirms actual floor condition.</small></div></div></div></div>`;bindDynamic()}
function renderLive(){const now=restaurantNow(),f=smartForecastDay(now.date);const rows=[30,60,90].map(m=>{const sum=windowSum(f,now.total+m),fl=modeledFloor(data,f,now.total+m,settings),st=staffingRecommendation(data,f,now.total+m,settings);return{m,sum,fl,st}});$('live').innerHTML=titleRow('Live Forecast','15-minute recalculation using FZ actual pace + Google Maps + local event impact')+liveForecastCard(f)+`<div class="card section-gap"><h2>DECISION WINDOW</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Horizon</th><th>New Tables</th><th>New Guests</th><th>Traffic Index</th><th>Modeled Floor</th><th>Recommended Servers</th><th>Confidence</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>+${r.m} min</b></td><td>${n1(r.sum.tables)}</td><td>${n0(r.sum.guests)}</td><td>${r.sum.index}/100</td><td>${r.fl?pct(r.fl.load):'—'}</td><td>${r.st.recommended}</td><td>${r.sum.confidence}%</td></tr>`).join('')}</tbody></table></div></div><div class="card section-gap"><h2>WHY THE LIVE FORECAST MOVED</h2>${forecastExplain(f)}<div class="explain"><div class="why"><span>Actual tables so far</span><b>${f.live.actualToNow}</b></div><div class="why"><span>Model expected so far</span><b>${n1(f.live.expectedToNow)}</b></div><div class="why"><span>Actual last 60 minutes</span><b>${f.live.last60Actual}</b></div><div class="why"><span>Model expected last 60 minutes</span><b>${n1(f.live.last60Expected)}</b></div></div></div>`}
function dailyActions(){return`<input id="dailyDate" type="date" value="${selectedDate}"><div class="tabs"><button data-dmode="hourly" class="${dailyMode==='hourly'?'active':''}">Hourly</button><button data-dmode="15min" class="${dailyMode==='15min'?'active':''}">15-Minute</button></div><button id="printDaily" class="action">Print</button><button id="exportDaily" class="action primary-mini">Export JSON</button>`}
function dailyHourRows(f){return f.hourly.map(h=>{const slots=f.slots.filter(s=>Math.floor(s.start/60)===h.hour),peak=slots.slice().sort((a,b)=>b.trafficIndex-a.trafficIndex)[0],mid=h.hour*60+30,fl=modeledFloor(data,f,mid,settings),st=staffingRecommendation(data,f,mid,settings);return`<tr><td><b>${formatMinute(h.hour*60)}</b></td><td>${n1(h.tables)}</td><td>${n0(h.guests)}</td><td>${peak?.reservations||0}</td><td><span class="pill ${levelClass(peak?.level)}">${peak?.level||'—'}</span> ${peak?.trafficIndex||0}/100</td><td>${fl?pct(fl.load):'—'}</td><td>${st.recommended}</td><td>${h.confidence}%</td></tr>`}).join('')}
function dailySlotRows(f){return f.slots.map(s=>{const fl=modeledFloor(data,f,s.start,settings),st=staffingRecommendation(data,f,s.start,settings);return`<tr><td><b>${s.label}</b></td><td>${n1(s.tables)}</td><td>${n0(s.guests)}</td><td>${n1(s.rangeLow)}–${n1(s.rangeHigh)}</td><td>${s.reservations}</td><td><span class="pill ${levelClass(s.level)}">${s.level}</span> ${s.trafficIndex}/100</td><td>${fl?pct(fl.load):'—'}</td><td>${st.recommended}</td><td>${s.confidence}%</td></tr>`}).join('')}
function googleDayRows(){const d=dayName(selectedDate).toLowerCase(),rows=googleLive?.weekly?.[d]||[];return rows.map(x=>`<tr class="${x.current?'hour-highlight':''}"><td>${esc(x.time)}</td><td>${x.busynessScore==null?'—':Math.round(x.busynessScore)+'%'}</td><td>${x.liveBusynessScore==null?'—':Math.round(x.liveBusynessScore)+'%'}</td><td>${x.current?'<span class="pill peak">CURRENT</span>':'—'}</td><td>${esc(x.info||'')}</td></tr>`).join('')}
function googleWeekBars(){if(!googleLive?.ok)return'';const days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];return days.map(d=>{const rows=googleLive.weekly?.[d]||[],peak=rows.slice().sort((a,b)=>(b.busynessScore||0)-(a.busynessScore||0))[0];return `<div class="day-card"><span>${d.slice(0,3).toUpperCase()}</span><b>${peak?.busynessScore==null?'—':Math.round(peak.busynessScore)}</b><small>${peak?.time||'No data'} peak</small></div>`}).join('')}
function renderGoogle(){const f=smartForecastDay(restaurantNow().date);$('google').innerHTML=titleRow('Google Live Traffic','Google Maps Popular Times + live visit signal for this exact Huntsville restaurant',`<button id="googleRefresh" class="action primary-mini">↻ Check Google Now</button>`)+googleCurrentCard()+`<div class="grid2 section-gap"><div class="card"><h2>GOOGLE POPULAR TIMES • ${dayName(selectedDate).toUpperCase()}</h2><div class="subtle">Typical hour-by-hour Google Maps busyness. Select another forecast day to compare its weekday pattern.</div>${googleLive?.ok?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Typical</th><th>Live</th><th>Status</th><th>Google Description</th></tr></thead><tbody>${googleDayRows()}</tbody></table></div>`:'<div class="empty">Waiting for the first successful Popular Times sync.</div>'}</div><div class="card"><h2>FZ + GOOGLE FUSION</h2><div class="explain"><div class="why"><span>FZ predicted tables today</span><b>${n0(f.totalTables)}</b></div><div class="why"><span>Google typical pattern weight</span><b>${settings.externalPatternWeight}%</b></div><div class="why"><span>Google live correction weight</span><b>${settings.externalLiveWeight}%</b></div><div class="why"><span>Google auto sync</span><b>10 • 12 • 2 • 4 • 6 • 8</b></div></div><div class="note"><b>Quota-safe schedule:</b> ${esc(googleScheduleLabel())}. Google does not replace Quick Board; Quick Board stays live between Google checks.</div></div></div><div class="card section-gap"><h2>GOOGLE WEEKLY PEAK SHAPE</h2><div class="week section-gap">${googleWeekBars()}</div></div><div class="card section-gap"><h2>SOURCE STATUS</h2><div class="status-line"><span class="status-chip">Place ID ${esc(GOOGLE_PLACE_ID)}</span><span class="status-chip">Provider ${esc(googleLive?.provider||'not connected')}</span><span class="status-chip">Source ${esc(googleLive?.source||'Google Maps Popular Times')}</span></div><div class="note">Popular Times are retained from the last successful Google response. If a later Google fetch omits Popular Times, FZ keeps the last-known-good pattern. Live busyness is only shown when Google actually returns a live score.</div></div>`;$('googleRefresh').onclick=()=>{if(confirm('Check Google now? Normally this uses one SerpApi search. If no Popular Times baseline has ever been captured, the first bootstrap may try up to three exact Google Maps routes, then it locks the first successful baseline. If this is within 90 minutes of a scheduled slot it will cover that slot.'))refreshGoogle(true)}}

function renderEvents(){const now=restaurantNow(),rows=upcomingEvents(localEvents,now.date,14),high=rows.filter(e=>e.impactLabel==='High'),med=rows.filter(e=>e.impactLabel==='Medium'),next=rows[0]||null,last=localEvents?.fetchedAt?new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(localEvents.fetchedAt)):'—';$('events').innerHTML=titleRow('Local Event Impact',`Huntsville • Madison • nearby North Alabama • upcoming 14-day watch`,`<button id="eventRefresh" class="action primary-mini">↻ Refresh Events Now</button>`)+`<div class="grid4">${kpi('Upcoming Events',rows.length,'Structured Google event results • next 14 days','blue')}${kpi('High Impact',high.length,'Potential restaurant-demand impact • heuristic','red')}${kpi('Medium Impact',med.length,'Worth watching for staffing / prep','orange')}${kpi('Next Event',next?next.date.slice(5):'—',next?esc(next.title):'No upcoming event returned','purple')}</div><div class="card section-gap"><div class="split-head"><div><h2>EVENT WATCH LIST</h2><div class="subtle">Each device checks at most once daily after 8:30 AM Central Time; the stable daily endpoint allows Vercel CDN reuse across devices.</div></div><span class="status-chip">Last sync ${esc(last)}</span></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Time</th><th>Event</th><th>Venue / Area</th><th>Type</th><th>Potential Impact</th><th>Forecast Lift</th></tr></thead><tbody>${rows.map(e=>`<tr><td><b>${esc(e.date)}</b></td><td>${esc(eventTime(e))}</td><td>${safeUrl(e.link)?`<a class="event-link" href="${esc(safeUrl(e.link))}" target="_blank" rel="noopener">${esc(e.title)}</a>`:esc(e.title)}</td><td>${esc(e.venue||e.area||'—')}<br><span class="subtle">${esc(e.area||'')}</span></td><td>${esc(e.category||'Local Event')}</td><td><span class="pill ${impactClass(e.impactLabel)}">${esc(e.impactLabel||'Low')} • ${e.impactScore||0}/100</span></td><td>${e.upliftPct?`Up to +${n0(e.upliftPct)}%`:'Info only'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No upcoming structured local events were returned in the latest daily scan.</div>'}</div><div class="grid2 section-gap"><div class="card"><h2>HOW EVENT IMPACT IS USED</h2><p class="method">FZ classifies concerts, expos/conventions, festivals, sports and other large local events. Major venues and Huntsville/Madison proximity increase the impact score. Forecast uplift is intentionally conservative and capped at ${settings.eventMaxUpliftPct}% per 15-minute slot. An event is a demand signal only; it never counts as an actual customer or reservation.</p><div class="status-line"><span class="status-chip">High ≥ 72</span><span class="status-chip">Medium 50–71</span><span class="status-chip">Low &lt; 50</span></div></div><div class="card"><h2>AUTO UPDATE & QUOTA</h2><div class="explain"><div class="why"><span>Automatic event check</span><b>Max 1 / device / day</b></div><div class="why"><span>Normal check</span><b>First app use after 8:30 AM CT</b></div><div class="why"><span>Google Maps busyness</span><b>Max 6 / day</b></div><div class="why"><span>Missed event check</span><b>Catches up on next app open</b></div></div><div class="note">The endpoint URL is stable for the day so Vercel CDN can share the same event response across devices. Manual refresh can use one additional SerpApi search.</div></div></div>`;$('eventRefresh').onclick=()=>{if(confirm('Refresh local events now? This can use one additional SerpApi search for today.'))refreshEvents(true)}}
function renderDaily(){const f=smartForecastDay(selectedDate),adv=advisor(data,f,settings),same=sameWeekdayHistory(selectedDate,8);$('daily').innerHTML=titleRow('Daily & Hourly Forecast',`${prettyDate(selectedDate)} • ${f.dayGroup}`,dailyActions())+`<div class="grid4">${kpi('Predicted Tables',n0(f.totalTables),`Range built from historical slot variance`,'blue')}${kpi('Predicted Guests',n0(f.totalGuests),`Average party ${f.totalTables?n1(f.totalGuests/f.totalTables):'0.0'}`,'green')}${kpi('Peak Window',f.peakSlot?formatMinute(f.peakSlot.start):'—',f.peakSlot?`${f.peakSlot.level} • index ${f.peakSlot.trafficIndex}/100`:'No data','red')}${kpi('Confidence',`${f.confidence}%`,`Exact weekday samples: ${f.recordedExactDays}`,'purple')}</div><div class="grid2 section-gap"><div class="card"><h2>HOURLY TRAFFIC SHAPE</h2>${hourlyChart(f)}</div><div class="card"><h2>MANAGER SUMMARY</h2><div class="explain"><div class="why"><span>Break window</span><b>${adv.breakText}</b></div><div class="why"><span>Potential cut</span><b>${adv.cutText}</b></div><div class="why"><span>Known reservations</span><b>${(data.reservations||[]).filter(r=>r.date===selectedDate).length}</b></div><div class="why"><span>Data group</span><b>${f.dayGroup}</b></div><div class="why"><span>Local events</span><b>${f.eventImpact?.count?`${f.eventImpact.count} • ${f.eventImpact.maxImpact}`:'None detected'}</b></div></div>${forecastExplain(f)}</div></div><div class="card section-gap"><div class="split-head"><div><h2>${dailyMode==='hourly'?'EVERY HOUR':'EVERY 15 MINUTES'}</h2><div class="subtle">Tables and guests are forecasts; floor load is modeled.</div></div></div><div class="table-wrap"><table class="data-table"><thead>${dailyMode==='hourly'?'<tr><th>Hour</th><th>Tables</th><th>Guests</th><th>Reservations</th><th>Traffic</th><th>Modeled Floor</th><th>Staff Target</th><th>Confidence</th></tr>':'<tr><th>Time</th><th>Tables</th><th>Guests</th><th>Range</th><th>Reservations</th><th>Traffic</th><th>Modeled Floor</th><th>Staff Target</th><th>Confidence</th></tr>'}</thead><tbody>${dailyMode==='hourly'?dailyHourRows(f):dailySlotRows(f)}</tbody></table></div></div><div class="card section-gap"><h2>SAME-WEEKDAY HISTORY • LAST ${same.length}</h2><div class="subtle">Direct comparison with previous ${dayName(selectedDate)}s used by the forecast engine.</div>${same.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Tables</th><th>Guests</th><th>Avg Party</th><th>Actual Peak Hour</th><th>Peak Tables</th></tr></thead><tbody>${same.map(x=>`<tr><td>${x.date}</td><td>${x.tables}</td><td>${x.guests}</td><td>${x.tables?n1(x.guests/x.tables):'—'}</td><td>${x.peak?formatMinute(x.peak.hour*60):'—'}</td><td>${x.peak?.tables||0}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No previous same-weekday history yet.</div>'}</div>`;bindDaily(f)}
function calendarForecasts(){return smartForecastRange(restaurantNow().date,30)}
function renderCalendar(){const fc=calendarForecasts(),first=dayName(fc[0].date),offset=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].indexOf(first);$('calendar').innerHTML=titleRow('30-Day Forecast Calendar','Every day contains a full hourly and 15-minute forecast • local events shown when discovered')+`<div class="card"><div class="calendar-key"><span><i class="dot" style="background:#16b96c"></i>Slow</span><span><i class="dot" style="background:#e0a717"></i>Normal</span><span><i class="dot" style="background:#ff8b19"></i>Busy</span><span><i class="dot" style="background:#ff4057"></i>Very Busy</span><span><i class="dot" style="background:#7a5cff"></i>Peak</span><span>🎟 Local event</span></div><div class="calendar section-gap">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="cal-head">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div></div>').join('')}${fc.map(f=>`<div class="cal-day ${f.date===selectedDate?'selected':''}" data-date="${f.date}"><strong>${Number(f.date.slice(-2))}</strong><i class="dot" style="background:${levelColor(f.peakSlot?.level||'Slow')}"></i><small>${n0(f.totalTables)} tables<br>${n0(f.totalGuests)} guests<br>Peak ${f.peakSlot?formatMinute(f.peakSlot.start):'—'}<br>${f.eventImpact?.count?`🎟 ${f.eventImpact.count} • ${f.eventImpact.maxImpact}<br>`:''}${f.confidence}% confidence</small></div>`).join('')}</div></div><div class="card section-gap"><h2>30-DAY LIST</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Day</th><th>Tables</th><th>Guests</th><th>Peak</th><th>Peak Level</th><th>Local Events</th><th>Confidence</th></tr></thead><tbody>${fc.map(f=>`<tr data-date="${f.date}" style="cursor:pointer"><td>${f.date}</td><td>${f.dayName}</td><td>${n0(f.totalTables)}</td><td>${n0(f.totalGuests)}</td><td>${f.peakSlot?formatMinute(f.peakSlot.start):'—'}</td><td><span class="pill ${levelClass(f.peakSlot?.level)}">${f.peakSlot?.level||'—'}</span></td><td>${f.eventImpact?.count?`${f.eventImpact.count} • ${f.eventImpact.maxImpact}`:'—'}</td><td>${f.confidence}%</td></tr>`).join('')}</tbody></table></div></div>`;bindDynamic()}
function renderStaffing(){const f=smartForecastDay(selectedDate),rows=f.hourly.map(h=>{const mid=h.hour*60+30,st=staffingRecommendation(data,f,mid,settings),fl=st.floor;return`<tr><td>${formatMinute(h.hour*60)}</td><td>${n1(h.tables)}</td><td>${fl?pct(fl.load):'—'}</td><td>${st.baseline}</td><td>${st.loadNeed}</td><td><b>${st.recommended}</b></td><td>${selectedDate===restaurantNow().date?data.staff.active:'—'}</td><td><span class="pill ${st.diff<0?'very':st.diff>1?'busy':''}">${selectedDate===restaurantNow().date?st.status:'PLAN'}</span></td></tr>`}).join('');$('staffing').innerHTML=titleRow('Staffing Intelligence',`${prettyDate(selectedDate)} • recommendation = operating baseline + modeled floor demand`,`<input id="staffDate" type="date" value="${selectedDate}">`)+`<div class="grid4">${kpi('Current Active Servers',selectedDate===restaurantNow().date?data.staff.active:'Plan mode',`On break ${data.staff.onBreak} • cut ${data.staff.cut}`,'blue')}${kpi('Peak Forecast',f.peakSlot?formatMinute(f.peakSlot.start):'—',`${f.peakSlot?.level||'—'} demand`,'red')}${kpi('Target Tables / Server',settings.targetTablesPerServer,'Owner-adjustable model setting','purple')}${kpi('Forecast Confidence',`${f.confidence}%`,`${f.recordedExactDays} exact weekday sample days`,'green')}</div><div class="card section-gap"><h2>HOURLY STAFF PLAN</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Hour</th><th>Forecast Tables</th><th>Modeled Floor</th><th>Baseline Staff</th><th>Load Need</th><th>Recommended</th><th>Active Now</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div><div class="note">The system never cuts or schedules employees automatically. It calculates a target and leaves the final decision to the Manager.</div></div>`;$('staffDate').onchange=e=>{selectedDate=e.target.value;renderStaffing()}}
function renderAdvisor(){const f=smartForecastDay(selectedDate),a=advisor(data,f,settings);$('advisor').innerHTML=titleRow('Break & Cut Advisor',`${prettyDate(selectedDate)} • forecast-based decision support`,`<input id="advisorDate" type="date" value="${selectedDate}">`)+`<div class="advisor-grid"><div class="card"><div class="subtle">BEST BREAK WINDOW</div><div class="big-advice purple">${a.breakText}</div><p class="method">Selected from low-traffic periods before the expected peak, with modeled floor pressure below the break threshold.</p><div class="signal">Break recommendation does not change Quick Board or employee status.</div></div><div class="card"><div class="subtle">POTENTIAL CUT WINDOW</div><div class="big-advice red">${a.cutText}</div><p class="method">Cut is only surfaced after the forecast peak when traffic is falling for consecutive intervals and modeled floor pressure is lower.</p><div class="signal warn">Manager must confirm actual service pace, kitchen load, waiting parties, reservations, and closing duties.</div></div></div><div class="card section-gap"><h2>15-MINUTE DECISION MAP</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Tables</th><th>Traffic</th><th>Modeled Floor</th><th>Staff Target</th><th>Confidence</th></tr></thead><tbody>${f.slots.map(s=>{const fl=modeledFloor(data,f,s.start,settings),st=staffingRecommendation(data,f,s.start,settings);return`<tr><td>${s.label}</td><td>${n1(s.tables)}</td><td><span class="pill ${levelClass(s.level)}">${s.level}</span> ${s.trafficIndex}</td><td>${fl?pct(fl.load):'—'}</td><td>${st.recommended}</td><td>${s.confidence}%</td></tr>`}).join('')}</tbody></table></div></div>`;$('advisorDate').onchange=e=>{selectedDate=e.target.value;renderAdvisor()}}
function renderHistory(){const now=restaurantNow(),from=addDays(now.date,-55),dates=[...new Set((data.events||[]).map(e=>e.date).filter(d=>d>=from&&d<now.date))],groups=['Mon–Thu','Fri–Sat','Sunday'],weeks=weeklyTrendRows(8),months=monthlyTrendRows(6);const groupRows=groups.map(g=>{const ds=dates.filter(d=>dayGroup(d)===g),hours=[];for(let h=11;h<=22;h++){const vals=ds.map(d=>(data.events||[]).filter(e=>e.date===d&&+e.hour===h).length);hours.push({h,avg:avg(vals)})}const peak=hours.slice().sort((a,b)=>b.avg-a.avg)[0];return{g,days:ds.length,hours,peak}});const histChart=g=>{const max=Math.max(1,...g.hours.map(x=>x.avg));return`<div class="chart">${g.hours.map(x=>`<div class="bar-col"><i style="height:${Math.max(2,x.avg/max*180)}px"></i><b>${x.h%12||12}${x.h<12?'a':'p'}</b></div>`).join('')}</div>`};$('history').innerHTML=titleRow('Historical Analytics','Weekly, monthly, and day-group intelligence • missing dates excluded')+`<div class="grid2"><div class="card"><h2>WEEKLY TREND • LAST ${weeks.length}</h2><div class="subtle">Average tables per recorded day</div>${weeks.length?trendBars(weeks):'<div class="empty">No weekly history yet.</div>'}<div class="table-wrap"><table class="data-table"><thead><tr><th>Week of</th><th>Recorded Days</th><th>Tables</th><th>Guests</th><th>Avg Tables / Day</th></tr></thead><tbody>${weeks.map(x=>`<tr><td>${x.period}</td><td>${x.recordedDays}</td><td>${x.tables}</td><td>${x.guests}</td><td>${n1(x.avgTables)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>MONTHLY TREND • LAST ${months.length}</h2><div class="subtle">Average tables per recorded day</div>${months.length?trendBars(months):'<div class="empty">No monthly history yet.</div>'}<div class="table-wrap"><table class="data-table"><thead><tr><th>Month</th><th>Recorded Days</th><th>Tables</th><th>Guests</th><th>Avg Tables / Day</th></tr></thead><tbody>${months.map(x=>`<tr><td>${x.period}</td><td>${x.recordedDays}</td><td>${x.tables}</td><td>${x.guests}</td><td>${n1(x.avgTables)}</td></tr>`).join('')}</tbody></table></div></div></div>`+groupRows.map(g=>`<div class="card section-gap"><div class="split-head"><div><h2>${g.g} • TRAFFIC BY HOUR</h2><div class="subtle">${g.days} recorded days • last 8 weeks</div></div><span class="pill">Peak avg ${g.peak?formatMinute(g.peak.h*60):'—'} • ${g.peak?n1(g.peak.avg):'0'} tables</span></div>${histChart(g)}</div>`).join('')+`<div class="card section-gap"><h2>DATA QUALITY</h2><div class="status-line"><span class="status-chip">Total events ${data.events.length}</span><span class="status-chip">Recorded dates ${[...new Set(data.events.map(e=>e.date))].length}</span><span class="status-chip">Reservations loaded ${data.reservations.length}</span><span class="status-chip">Physical floor tables ${data.floor.total}</span></div><div class="note">Historical zeroes are counted only inside dates that contain recorded seating history. Entire missing dates are not treated as zero-demand days.</div></div>`}
function renderAccuracy(){const a=accuracyReport(data),acc=a.accuracy==null?'—':Math.round(a.accuracy*100)+'%';$('accuracy').innerHTML=titleRow('Forecast vs Actual','Local audit trail from forecasts created every refresh on this device')+`<div class="grid4">${kpi('Measured Accuracy',acc,`${a.count} completed 15-minute forecast checks`,'blue')}${kpi('Weighted Abs. % Error',a.wape==null?'—':Math.round(a.wape*100)+'%','Includes zero-traffic slots in total error','orange')}${kpi('Mean Abs. Table Error',a.mae==null?'—':n1(a.mae),'Average tables missed per 15-minute slot','red')}${kpi('Audit Retention','45 days','One snapshot per 15-minute refresh bucket','purple')}</div><div class="card section-gap"><h2>ACCURACY BY FORECAST HORIZON</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Lead Time</th><th>Checks</th><th>Accuracy</th><th>WAPE</th><th>Mean Abs. Error</th></tr></thead><tbody>${a.byHorizon.map(x=>`<tr><td><b>${x.label}</b></td><td>${x.count}</td><td>${x.accuracy==null?'—':Math.round(x.accuracy*100)+'%'}</td><td>${x.wape==null?'—':Math.round(x.wape*100)+'%'}</td><td>${x.mae==null?'—':n1(x.mae)}</td></tr>`).join('')}</tbody></table></div></div><div class="card section-gap"><h2>RECENT FORECAST CHECKS</h2>${a.rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Time</th><th>Lead</th><th>Predicted</th><th>Actual</th><th>Absolute Error</th><th>Confidence</th></tr></thead><tbody>${a.rows.slice(0,120).map(r=>`<tr><td>${r.date}</td><td>${formatMinute(r.start)}</td><td>${r.leadMinutes!=null?Math.round(r.leadMinutes)+'m':'—'}</td><td>${n1(r.predicted)}</td><td>${r.actual}</td><td>${n1(r.error)}</td><td>${r.confidence}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Accuracy data will appear after forecasted time slots pass. The app does not invent accuracy before it has actual results.</div>'}</div>`}
function renderSettings(){const field=(key,label,help,min=0,max=999)=>`<div class="setting"><label>${esc(label)}</label><input data-setting="${key}" type="number" min="${min}" max="${max}" value="${settings[key]}"><small class="subtle">${esc(help)}</small></div>`;const textField=(key,label,help)=>`<div class="setting setting-wide"><label>${esc(label)}</label><input data-setting-text="${key}" type="text" value="${esc(settings[key]||'')}"><small class="subtle">${esc(help)}</small></div>`;$('settings').innerHTML=titleRow('Model, Google & Local Event Settings','Owner-controlled parameters stored locally on this device')+`<div class="card"><h2>GOOGLE MAPS LIVE SIGNAL</h2><div class="setting-grid section-gap">${textField('externalEndpoint','Google Live API endpoint','Vercel deployment: /api/google-live. GitHub Pages: enter the full HTTPS URL of your deployed bridge.')}${field('externalPatternWeight','Google typical-pattern weight (%)','How strongly Popular Times reshapes hourly demand.',0,50)}${field('externalLiveWeight','Google live correction weight (%)','How strongly live busyness corrects the next 120 minutes.',0,70)}</div><div class="status-line"><span class="status-chip">Place ID ${GOOGLE_PLACE_ID}</span><span class="status-chip">${googleLive?.ok?(googleLive.lastKnownGood?'GOOGLE MAPS • SHARED LAST GOOD':'GOOGLE MAPS • CONNECTED'):'GOOGLE MAPS • WAITING'}</span></div><div class="note"><b>Quota-safe automatic schedule (Central Time):</b> 10:00 AM • 12:00 PM • 2:00 PM • 4:00 PM • 6:00 PM • 8:00 PM. Missed slots are skipped, not replayed.</div></div><div class="card section-gap"><h2>LOCAL EVENT IMPACT SIGNAL</h2><div class="setting-grid section-gap">${textField('eventEndpoint','Local Event API endpoint','Vercel deployment: /api/local-events. Uses the same server-side SERPAPI_KEY.')}${field('eventMaxUpliftPct','Maximum event uplift per slot (%)','Conservative cap applied only around relevant event windows.',0,25)}</div><div class="status-line"><span class="status-chip">Huntsville • Madison • nearby</span><span class="status-chip">${localEvents?.ok?'EVENT FEED CONNECTED':'EVENT FEED WAITING'}</span></div><div class="note"><b>Quota-safe:</b> each device performs at most one automatic event check per day after 8:30 AM Central Time; Vercel CDN can reuse the daily response across devices. The scan looks ahead for concerts, expos/conventions, festivals, sports, fairs and other local events.</div><div class="action-row section-gap"><button id="testEvents" class="action">Test Local Events</button></div></div><div class="card section-gap"><h2>FZ FORECAST MODEL</h2><div class="setting-grid section-gap">${field('avgDiningMinutes','Average dining duration (minutes)','Used only for future Floor Load modeling.',30,180)}${field('targetTablesPerServer','Target active tables per server','Load-based staffing requirement.',1,10)}${field('recencyHalfLifeDays','Historical recency window','Lower value makes recent weeks matter more.',14,180)}${field('liveUpdateMinutes','Quick Board refresh interval (minutes)','Minimum recommended: 5 minutes.',5,60)}</div></div><div class="card section-gap"><h2>BASE SERVER DEPLOYMENT</h2><div class="setting-grid section-gap">${field('weekdayAM','Mon–Thu AM servers','Operating baseline.',1,20)}${field('weekdayPM','Mon–Thu PM servers','Operating baseline.',1,20)}${field('fridayAM','Friday AM servers','Operating baseline.',1,20)}${field('fridayPM','Friday PM servers','Operating baseline.',1,20)}${field('saturdayAM','Saturday AM servers','Operating baseline.',1,20)}${field('saturdayPM','Saturday PM servers','Operating baseline.',1,20)}${field('sundayAM','Sunday AM servers','Operating baseline.',1,20)}${field('sundayPM','Sunday PM servers','Operating baseline.',1,20)}</div><div class="action-row section-gap"><button id="saveSettings" class="action primary-mini">Save Settings</button><button id="resetSettings" class="action">Reset Defaults</button><button id="testGoogle" class="action">Test Google Live</button></div></div><div class="card section-gap"><h2>FUSION METHOD</h2><p class="method">Primary model: exact weekday FZ history → Mon–Thu/Fri–Sat/Sunday fallback → recency → month/season → reservations → same-day pace/momentum. External layers: Google Maps Popular Times reshapes the hourly curve, Google live busyness adjusts the next 120 minutes when available, and local events can add a conservative time-window uplift. Event signals never count as actual customers or reservations, and external values are never fabricated.</p></div>`;document.querySelectorAll('[data-setting]').forEach(i=>i.onchange=()=>{settings[i.dataset.setting]=Math.max(+i.min,Math.min(+i.max,+i.value||0))});document.querySelectorAll('[data-setting-text]').forEach(i=>i.onchange=()=>settings[i.dataset.setting]=i.value.trim());$('saveSettings').onclick=()=>{saveSettings();scheduleRefresh();showBanner('Settings saved. FZ + Google forecasts recalculated.','ok');renderCurrent()};$('resetSettings').onclick=()=>{settings={...DEFAULT_SETTINGS};saveSettings();renderSettings()};$('testGoogle').onclick=()=>{if(confirm('Check Google now? Normally this uses one SerpApi search. If no Popular Times baseline has ever been captured, the first bootstrap may try up to three exact Google Maps routes, then it locks the first successful baseline. If this is within 90 minutes of a scheduled slot it will cover that slot.'))refreshGoogle(true)};$('testEvents').onclick=()=>{if(confirm('Check local events now? This can use one extra SerpApi search for today.'))refreshEvents(true)}}
function bindDaily(f){$('dailyDate').onchange=e=>{selectedDate=e.target.value;renderDaily()};document.querySelectorAll('[data-dmode]').forEach(b=>b.onclick=()=>{dailyMode=b.dataset.dmode;renderDaily()});$('printDaily').onclick=()=>window.print();$('exportDaily').onclick=()=>{const blob=new Blob([JSON.stringify(f,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`FZ_Traffic_Forecast_${f.date}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
function bindDynamic(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>switchView(b.dataset.go));document.querySelectorAll('[data-date]').forEach(el=>el.onclick=()=>{selectedDate=el.dataset.date;switchView('daily')})}
function renderCurrent(){if(!data)return;({dashboard:renderDashboard,live:renderLive,google:renderGoogle,events:renderEvents,daily:renderDaily,calendar:renderCalendar,staffing:renderStaffing,advisor:renderAdvisor,history:renderHistory,accuracy:renderAccuracy,settings:renderSettings}[currentView]||renderDashboard)()}
function switchView(v){currentView=v;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hidden',x.id!==v));document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));renderCurrent();window.scrollTo({top:0,behavior:'smooth'})}
function showBanner(msg,type='warn'){$('banner').textContent=msg;$('banner').classList.remove('hidden');$('banner').style.background=type==='ok'?'#ebfbf3':'#fff4e8';$('banner').style.borderColor=type==='ok'?'#bdebd3':'#ffd9a7';setTimeout(()=>$('banner').classList.add('hidden'),5000)}
async function hydrateSharedGoogleCache(){try{const shared=await fetchGoogleLive(settings,{cacheOnly:true});if(!shared?.ok)return googleLive;const currentAt=Number(googleLive?.fetchedAt)||0,sharedAt=Number(shared?.fetchedAt)||0;if(!googleLive?.ok||sharedAt>=currentAt){googleLive={...shared,lastKnownGood:true,cacheState:'shared-durable'};saveGoogleCache(shared);$('googleStatus').textContent='GOOGLE MAPS • SHARED LAST GOOD'}return googleLive}catch{return googleLive}}
async function refreshGoogle(manual=false,autoSlot=null){$('googleStatus').textContent='GOOGLE SYNCING…';if(autoSlot!=null)markGoogleSlot(autoSlot);if(manual)coverNearbySlotWithManual();const fresh=await fetchGoogleLive(settings,{force:manual});googleLastAttempt={at:Date.now(),ok:Boolean(fresh?.ok),error:fresh?.latestAttemptError||fresh?.error||''};if(fresh?.ok){const retained=Boolean(fresh.lastKnownGood);googleLive={...fresh,lastKnownGood:retained,cacheState:retained?'shared-durable':(fresh.edgeAgeSeconds>0?'shared-edge':'fresh')};saveGoogleCache(fresh);$('googleStatus').textContent=retained?'GOOGLE MAPS • LAST GOOD':(Number.isFinite(fresh.liveScore)?'GOOGLE LIVE • CONNECTED':'GOOGLE MAPS • POPULAR TIMES');if(manual)showBanner(retained?'Latest Google check had no Popular Times, so FZ kept the shared last successful Popular Times pattern.':'Google check complete. Popular Times retained and refreshed when available.','ok')}else{let cached=loadGoogleCache();if(!cached?.ok){await hydrateSharedGoogleCache();cached=googleLive?.ok?googleLive:null}if(cached?.ok){googleLive={...cached,lastKnownGood:true,lastAttemptError:fresh?.error||'Google did not return Popular Times in this check.',lastAttemptAt:Date.now()};$('googleStatus').textContent='GOOGLE MAPS • LAST GOOD';if(manual)showBanner('This Google check did not include Popular Times, so FZ kept the last successful Popular Times pattern.','ok')}else{$('googleStatus').textContent='GOOGLE MAPS • WAITING';googleLive=fresh;if(manual)showBanner('Google did not return Popular Times yet: '+(fresh?.error||'waiting for next scheduled check'))}}if(data)renderCurrent();return googleLive}
async function maybeAutoRefreshGoogle(){const slot=latestDueGoogleSlot();if(slot==null){if(!googleLive?.ok)await hydrateSharedGoogleCache();if(googleLive?.ok)$('googleStatus').textContent=googleLive.lastKnownGood?'GOOGLE MAPS • LAST GOOD':'GOOGLE MAPS • CACHED';return googleLive}return refreshGoogle(false,slot)}
async function refreshEvents(manual=false){$('eventStatus').textContent='EVENTS SYNCING…';if(manual||shouldAutoRefreshEvents())markEventChecked(manual);const fresh=await fetchLocalEvents(settings,{force:manual});eventLastAttempt={at:Date.now(),ok:Boolean(fresh?.ok),error:fresh?.error||''};if(fresh?.ok&&Array.isArray(fresh.events)&&fresh.events.length){localEvents={...fresh,lastKnownGood:false,cacheState:fresh.edgeAgeSeconds>0?'shared-edge':'fresh'};saveEventCache(fresh);$('eventStatus').textContent=`EVENTS • ${fresh.events.length} FOUND`;const nextHigh=upcomingEvents(fresh,restaurantNow().date,7).find(e=>e.impactLabel==='High');if(!manual&&nextHigh)showBanner(`LOCAL EVENT ALERT • ${nextHigh.title} • ${nextHigh.date}${Number.isFinite(nextHigh.startMinute)?' '+formatMinute(nextHigh.startMinute):''} • HIGH potential impact`);if(manual)showBanner(`Local-event scan complete: ${fresh.events.length} event${fresh.events.length===1?'':'s'} found. Forecasts recalculated.`, 'ok')}else{const cached=loadEventCache();if(cached?.ok){localEvents={...cached,lastKnownGood:true,lastAttemptError:fresh?.error||'Latest scan returned no structured events.'};$('eventStatus').textContent='EVENTS • LAST GOOD';if(manual)showBanner('Latest event scan returned no structured events, so FZ kept the last successful event list.','ok')}else{localEvents=fresh;$('eventStatus').textContent='EVENTS • WAITING';if(manual)showBanner('No structured local events returned yet: '+(fresh?.error||'Google returned no event pack'))}}if(data)renderCurrent();return localEvents}
async function maybeAutoRefreshEvents(){if(!shouldAutoRefreshEvents()){if(localEvents?.ok)$('eventStatus').textContent=localEvents.lastKnownGood?'EVENTS • LAST GOOD':'EVENTS • CACHED';return localEvents}return refreshEvents(false)}
async function refreshData(manual=false){$('boardStatus').textContent='SYNCING…';try{data=await fetchQuickBoardData();$('boardStatus').textContent='LIVE • READ ONLY';$('lastSync').textContent='FZ '+new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit',second:'2-digit'}).format(new Date(data.fetchedAt));if(manual){await maybeAutoRefreshGoogle();await maybeAutoRefreshEvents();}try{saveForecastSnapshot(smartForecastDay(restaurantNow().date))}catch(e){console.warn('Forecast audit snapshot:',e)}renderCurrent();if(manual)showBanner('Quick Board refreshed. Google follows the quota-safe 6-times/day schedule; local events scan at most once/day.','ok')}catch(e){console.error(e);$('boardStatus').textContent='CONNECTION ERROR';showBanner('Quick Board connection error: '+(e.message||e))}}
function scheduleRefresh(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>refreshData(false),Math.max(5,settings.liveUpdateMinutes)*60000);if(window.__googleTimer)clearInterval(window.__googleTimer);window.__googleTimer=setInterval(()=>maybeAutoRefreshGoogle(),60000);if(window.__eventTimer)clearInterval(window.__eventTimer);window.__eventTimer=setInterval(()=>maybeAutoRefreshEvents(),5*60000)}
$('nav').onclick=e=>{const b=e.target.closest('button[data-view]');if(b)switchView(b.dataset.view)};$('refreshBtn').onclick=()=>refreshData(true);$('logoutBtn').onclick=()=>signOut(auth);$('loginBtn').onclick=async()=>{const u=$('user').value.trim(),p=$('pass').value;if(!u||!p){$('loginMsg').textContent='Enter Owner username and password.';return}try{$('loginBtn').disabled=true;$('loginMsg').textContent='Signing in…';await signInWithEmailAndPassword(auth,emailFor(u),p)}catch(e){$('loginMsg').textContent='Login failed: '+(e.code||e.message)}finally{$('loginBtn').disabled=false}};$('pass').onkeydown=e=>{if(e.key==='Enter')$('loginBtn').click()};
onAuthStateChanged(auth,async user=>{if(!user){profile=null;$('loginView').classList.remove('hidden');$('app').classList.add('hidden');return}try{$('loginMsg').textContent='Verifying Owner access…';const snap=await getDoc(doc(db,'users',user.uid)),p=snap.exists()?snap.data():null;if(!p||p.active===false||p.role!=='owner'){await signOut(auth);$('loginMsg').textContent='Owner account required.';return}profile=p;$('loginView').classList.add('hidden');$('app').classList.remove('hidden');selectedDate=restaurantNow().date;clock();if(clockTimer)clearInterval(clockTimer);clockTimer=setInterval(clock,1000);googleLive=loadGoogleCache();if(googleLive?.ok)$('googleStatus').textContent='GOOGLE MAPS • CACHED';await hydrateSharedGoogleCache();localEvents=loadEventCache();if(localEvents?.ok)$('eventStatus').textContent='EVENTS • CACHED';await refreshData(false);await maybeAutoRefreshGoogle();await maybeAutoRefreshEvents();if(currentView!=='dashboard')switchView(currentView);try{saveForecastSnapshot(smartForecastDay(restaurantNow().date))}catch{}scheduleRefresh()}catch(e){console.error(e);$('loginMsg').textContent='Owner verification failed: '+(e.code||e.message);try{await signOut(auth)}catch{}}});
